/* Global Styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #1a1a1a;
  color: #e0e0e0;
  line-height: 1.6;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 20px;
}

/* Header */
header {
  text-align: center;
  margin-bottom: 30px;
  padding: 20px;
  background-color: #2a2a2a;
  border-radius: 10px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

header h1 {
  color: #d4af37;
  font-size: 2.5em;
  margin-bottom: 10px;
}

header p {
  color: #999;
  font-size: 1.2em;
}

/* Main Game Area */
.game-area {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 20px;
  height: 70vh;
}

/* Chat Container */
.chat-container {
  background-color: #2a2a2a;
  border-radius: 10px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 15px;
  background-color: #1e1e1e;
  border-radius: 5px;
  margin-bottom: 15px;
}

.message {
  margin-bottom: 15px;
  padding: 10px;
  border-radius: 5px;
  animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.player-message {
  background-color: #3a4a5a;
  border-left: 4px solid #4a90e2;
}

.gm-message {
  background-color: #4a3a5a;
  border-left: 4px solid #d4af37;
}

.message strong {
  color: #fff;
  display: block;

